    assert.equal(created.value.taskspace.protectedExecutionEligible, true);
    assert.equal(created.value.taskspace.accessMode, 'conversation');
    assert.equal(created.value.taskspace.harnessPort, 23001);
    const replayed = await request(port, 'POST', '/v1/taskspaces', token, payload);
    assert.equal(replayed.status, 200);
    assert.equal(calls.filter((entry) => entry[0] === 'create').length, 1);

    const outputRoot = path.join(root, 'taskspaces', payload.taskId, 'uploads');
