    assert.equal(replayedPrepare.value.execution.idempotent, true);
    assert.equal(replayedPrepare.value.execution.authorityClass, 'production-read-only');
    assert.equal(replayedPrepare.value.execution.actionCeiling, 'read-only');
    assert.deepEqual(replayedPrepare.value.execution.ownedPaths, []);
    assert.equal(acceptanceCalls.length, 0);
    assert.equal(Object.hasOwn(authorityCalls.at(-1), 'conversationTaskPreparationSupported'), false);
