    assert.equal(secondPrepare.status, 200);
    assert.equal(secondPrepare.value.execution.generation, 2);
    assert.equal(secondPrepare.value.execution.authorityClass, 'production-read-only');
    assert.equal(secondPrepare.value.execution.actionCeiling, 'read-only');
