test('execution-context TaskSpace action accepts only bounded identity lookup fields', () => {
  const request = {
    action: 'execution-context',
    projectSlug: 'validation-project',
    taskId: 'c-test-task',
    conversationId: 'conversation:alice:1',
    actorUserId: ALICE_USER_ID,
    dshSessionId: 'session:alice:1',
    rpcId: 'rpc:alice:1',
    textDigest: 'a'.repeat(64),
  };
  assert.deepEqual(validateTaskspaceAction(request), request);
  assert.throws(() => validateTaskspaceAction({ ...request, actionCeiling: 'workspace-write' }), /unsupported field/u);
  assert.throws(() => validateTaskspaceAction({ ...request, actorUserId: 'alice' }), /actorUserId is invalid/u);
  assert.throws(() => validateTaskspaceAction({ ...request, textDigest: 'short' }), /textDigest is invalid/u);
});

test('checkpoint TaskSpace action accepts only the exact bounded source mutation schema', () => {
  const request = {
    action: 'checkpoint',
    paths: ['src/app.mjs', 'tests/app.test.mjs'],
    message: 'Checkpoint reviewed source',
    expectedHead: 'a'.repeat(40),
    expectedWorkspaceFingerprint: 'b'.repeat(64),
  };
  assert.deepEqual(validateTaskspaceAction(request), request);
  for (const invalid of [
    { ...request, paths: [] },
    { ...request, paths: ['src/app.mjs', 'src/app.mjs'] },
    { ...request, paths: ['../app.mjs'] },
    { ...request, paths: ['src/node_modules/app.mjs'] },
    { ...request, message: 'bad\nmessage' },
    { ...request, message: '\ud800' },
    { ...request, message: '界'.repeat(167) },
    { ...request, expectedHead: 'A'.repeat(40) },
    { ...request, expectedWorkspaceFingerprint: 'short' },
    { ...request, actorUserId: ALICE_USER_ID },
    { ...request, authority: 'writer' },
    { ...request, acceptancePassed: true },
    { ...request, binding: { trusted: true } },
  ]) {
    assert.throws(() => validateTaskspaceAction(invalid));
  }
});

