test('Manager socket output preserves archive bytes above 2 MiB and enforces response limits', async () => {
  const root = await mkdtemp(path.join(os.tmpdir(), 'forge-manager-output-socket-'));
  const socketPath = process.platform === 'win32'
    ? `\\\\.\\pipe\\forge-manager-output-${process.pid}-${Date.now()}`
    : path.join(root, 'manager.sock');
  const token = 's'.repeat(64);
  const original = Buffer.from('中文归档😀\n'.repeat(220_000));
  const sha256 = crypto.createHash('sha256').update(original).digest('hex');
  const responseBody = Buffer.from(JSON.stringify({ ok: true, name: 'conversation.md', bytes: original.length,
    sha256, base64: original.toString('base64') }));
  assert.ok(original.length > 2 * 1024 * 1024);
  const server = http.createServer((request, response) => {
    assert.equal(request.headers.authorization, `Bearer ${token}`);
    response.setHeader('content-type', 'application/json');
    if (request.url.endsWith('/oversized.md')) {
      // The actual wire response exceeds the archive cap without one giant fixture allocation.
      response.write('{"base64":"');
      const chunk = Buffer.alloc(1024 * 1024, 'A');
      for (let index = 0; index < 70; index += 1) response.write(chunk);
      response.end('"}');
    } else response.end(responseBody);
  });
  await listenSocket(server, socketPath);
  try {
    const manager = createManagerClient({ socketPath, token, timeoutMs: 2_000 });
    const output = await manager.output('task-output', 'session-output', 'a'.repeat(64), 'conversation.md');
    assert.equal(output.bytes, original.length, 'archive response must survive the socket receive buffer');
    const downloaded = Buffer.from(output.base64, 'base64');
    assert.deepEqual(downloaded, original);
    assert.equal(crypto.createHash('sha256').update(downloaded).digest('hex'), output.sha256);
    await assert.rejects(manager.health(), { code: 'MANAGER_RESPONSE_TOO_LARGE', status: 502 });
    await assert.rejects(manager.output('task-output', 'session-output', 'a'.repeat(64), 'oversized.md'),
      { code: 'MANAGER_RESPONSE_TOO_LARGE', status: 502 });
  } finally {
    await close(server);
    await rm(root, { recursive: true, force: true });
  }
});

test('manager quarantines raw intake and promotes reviewed material with hash, traversal and idempotency gates', async () => {
  const root = await mkdtemp(path.join(os.tmpdir(), 'forge-project-materials-'));
  const intakeRoot = path.join(root, 'intake');
  const token = 'g'.repeat(64);
  const controlScript = path.join(root, 'taskspacectl.sh');
  const sourceRelative = 'incoming/2026-08-28/review-batch/业务需求.md';
  const sourcePath = path.join(intakeRoot, ...sourceRelative.split('/'));
  await mkdir(path.dirname(sourcePath), { recursive: true });
  await writeFile(controlScript, '#!/bin/sh\nexit 0\n');
  await writeFile(sourcePath, '# 业务需求\n');
  await writeFile(path.join(intakeRoot, '.upload-audit.jsonl'), `${JSON.stringify({
    schemaVersion: 1,
    at: '2026-08-27T10:00:00.000Z',
    path: `/project-inputs/${sourceRelative}`,
    sha256: 'legacy-value-not-trusted-by-manager',
    readable: {
      format: '文本',
      path: `/project-inputs/${sourceRelative}`,
      status: 'native',
    },
  })}\n`);
  const expectedSha256 = '245cfc885b4300fe884a24f8bb539ccc76f4d56683b92d66b3b4a26795e04275';
  const server = createConversationManager({
    projectRoot: root,
    projectSlug: 'material-project',
    intakeRoot,
    controlScript,
    managerToken: token,
    auditPath: path.join(root, 'ops', 'manager-audit.jsonl'),
  });
  const port = await listen(server);
  try {
    const before = await request(port, 'GET', '/v1/materials?includeIntake=true', token);
    assert.equal(before.status, 200);
    assert.equal(before.value.accepted.total, 0);
    assert.equal(before.value.intake.total, 1);
    assert.equal(before.value.intake.items[0].attribution.status, 'legacy-unattributed');

    const body = {
      actorId: '11111111-1111-4111-8111-111111111111',
      actorUsername: 'admin',
      category: 'business',
      expectedSha256,
      requestId: 'material:review:00000001',
      sourcePath: sourceRelative,
    };
    const promoted = await request(port, 'POST', '/v1/materials/promote', token, body);
    assert.equal(promoted.status, 200, JSON.stringify(promoted.value));
    assert.equal(promoted.value.idempotent, false);
    assert.equal(promoted.value.material.readable.status, 'native');
    assert.equal(await readFile(path.join(root, 'shared-inputs', 'accepted', 'business', '业务需求.md'), 'utf8'), '# 业务需求\n');

    const after = await request(port, 'GET', '/v1/materials?includeIntake=true', token);
    assert.equal(after.value.accepted.total, 1);
    assert.equal(after.value.accepted.items[0].governanceStatus, 'approved');
    assert.equal(after.value.accepted.items[0].readable.status, 'native');
    assert.equal(after.value.intake.total, 0);

    const replayed = await request(port, 'POST', '/v1/materials/promote', token, body);
    assert.equal(replayed.status, 200);
    assert.equal(replayed.value.idempotent, true);

    const changed = await request(port, 'POST', '/v1/materials/promote', token, { ...body, expectedSha256: 'a'.repeat(64) });
    assert.equal(changed.status, 409);
    assert.equal(changed.value.code, 'MATERIAL_SOURCE_CHANGED');
    const traversal = await request(port, 'POST', '/v1/materials/promote', token, { ...body, sourcePath: '../escape.md' });
    assert.equal(traversal.status, 400);

    const audit = (await readFile(path.join(root, 'shared-inputs', 'governance', 'material-events.jsonl'), 'utf8')).trim().split('\n');
    assert.equal(audit.length, 1);
    assert.equal(JSON.parse(audit[0]).source.attribution.status, 'legacy-unattributed');

    const outside = path.join(root, 'outside.md');
    const linked = path.join(intakeRoot, 'linked.md');
    await writeFile(outside, 'outside');
    try {
      await symlink(outside, linked);
      const listed = await request(port, 'GET', '/v1/materials?includeIntake=true', token);
      assert.equal(listed.value.intake.items.some((item) => item.path === 'linked.md'), false);
    } catch (error) {
      if (!['EPERM', 'EACCES'].includes(error.code)) throw error;
    }
  } finally {
    await close(server);
    await rm(root, { recursive: true, force: true });
  }
});

