  assert.deepEqual(await Promise.all(paths.map(file => readFile(path.join(workspace, file)))), upstreamBytes);
  assert.deepEqual(receiptReads, priorReceiptReads, 'Zero UI Host obligations must not reuse database Host receipts');
  assert.deepEqual(JSON.parse(await readFile(path.join(uiDirectory, '阶段宿主验证回执.json'), 'utf8')), []);
  assert.deepEqual(await readFile(path.join(uiDirectory, '阶段候选检查结果.json')), uiAssessmentBytes);
  assert.equal(await readFile(path.join(uiDirectory, '模型最终回答.txt'), 'utf8'), uiResponse);
  const uiReplay = await request(port, 'POST', route, token, uiContinue);
