  backendProposal.payload.changedPaths = [backendPath];
  const backendLive = await inventoryWorkspace(workspace, inventoryLimits);
  const backendReferences = backendPhase.hostVerificationProfiles.map(profile => {
    const receiptId = crypto.randomUUID();
    receipts.set(receiptId, createForgePhaseHostReceipt({ projectSlug, taskId, profile, receiptId,
      sourceCommit, sourceFingerprint: backendLive.workspaceFingerprint,
      selectors: profile.startsWith('backend-module-') ? { modules: ['forge-server/forge-business/forge-business-core'] } : {} }));
    return { profile, receiptId };
  });
  backendProposal.payload.apiImplementation.hostReceipts = backendReferences.slice(0, 2).map(({ receiptId }) => ({ receiptId }));
  setCompleted(uiCompleted.value, backendProposal, 50);
  const readsBeforeBackend = [...receiptReads];
  const backendMissing = await capture(uiCompleted.value.execution.executionId);
  assert.equal(backendMissing.status, 200, JSON.stringify(backendMissing.value));
  assert.equal(backendMissing.value.assessment.code, 'PHASE_HOST_VERIFICATION_REQUIRED');
  assert.deepEqual(backendMissing.value.assessment.hostVerification.missingProfiles, backendPhase.hostVerificationProfiles);
  assert.deepEqual(receiptReads, readsBeforeBackend, 'Untagged receipt IDs must not be treated as verified evidence');
  const backendDirectory = path.join(phaseDirectory, 'browser-attempts', uiCompleted.value.execution.executionId);
