  assert.equal(backendResumedState.activeAttempt.executionGeneration, backendState.activeAttempt.executionGeneration + 1);
  assert.equal(backendResumedState.revision, backendState.revision);
  assert.deepEqual(backendResumedState.history, backendState.history);
  assert.deepEqual(backendResumedState.acceptedArtifacts, backendState.acceptedArtifacts);
  assert.deepEqual(await Promise.all(paths.map(file => readFile(path.join(workspace, file)))), upstreamBytes);
  assert.deepEqual(await Promise.all(retainedNames.map(name => readFile(path.join(backendDirectory, name)))), backendRetained);
  const backendCorrected = structuredClone(backendProposal);
