  const resumedLookup = Object.fromEntries(['projectSlug', 'taskId', 'actorUserId', 'conversationId', 'dshSessionId', 'rpcId', 'textDigest'].map(key => [key, resumed.value.execution[key]]));
  await readProtectedExecutionContext({ projectRoot: root, taskMetadata: metadata, lookup: resumedLookup });
