  assert.deepEqual(committedPreparation.acceptedApiContract, recovered);
  await writeFile(path.join(workspace, ownedTest), '// already published repair after phase completion\n');
  execFileSync('git', ['-C', workspace, 'add', ownedTest]);
  execFileSync('git', ['-C', workspace, 'commit', '--quiet', '-m', 'fixture already published repair']);
  const publishedSource = await inventoryWorkspace(workspace, inventoryLimits);
  assert.notEqual(publishedSource.workspaceFingerprint, committed.workspaceFingerprint);
  const transitionFile = path.join(root, 'taskspaces', '.broker', 'source-transitions', `${taskId}.json`);
  await mkdir(path.dirname(transitionFile), { recursive: true, mode: 0o700 });
  const transitionPayload = {
    schemaVersion: 1, operationId: crypto.randomUUID(),
    task: { projectSlug, taskId, actorUserId: ALICE_USER_ID, actorUsername: 'alice', conversationId, dshSessionId: sessionId },
    from: { head: committed.head, fingerprint: publishedSource.workspaceFingerprint },
    to: { head: publishedSource.head, fingerprint: publishedSource.workspaceFingerprint },
    canonicalHead: committed.head, phase: 'checkpointed',
    sourceAuthority: { executionId: crypto.randomUUID(), generation: 1, contractId: '6'.repeat(64),
      productionAuthorityDigest: '7'.repeat(64), controllerGrantDigest: '8'.repeat(64), actionCeiling: 'release',
      issuedAt: '2026-09-12T00:00:00.000Z', expiresAt: '2026-09-12T00:15:00.000Z' },
    digestAlgorithm: 'sha256', digestEncoding: 'canonical-json-v1',
  };
  const saveTransition = async payload => writeFile(transitionFile,
    `${JSON.stringify({ ...payload, digest: sourceTransitionCanonicalDigest(payload) })}\n`, { mode: 0o600 });
  const published = { schemaVersion: 1, projectSlug, availability: 'ready', occupied: false,
    operation: { action: 'release', status: 'success', stage: 'complete', taskId: 'another-task', actorId: 'bob',
      commit: 'f'.repeat(40), services: ['forge-admin', 'forge-app', 'forge-flow', 'forge-ui'] } };
  const repairText = '请继续修改当前任务。修复后端接口和直接相关测试。';
