  const apiIncompleteCapture = await request(port, 'POST', `/v1/taskspaces/${taskId}/phase-terminal/capture`, token,
    { projectSlug, taskId, actorUserId: ALICE_USER_ID, actorUsername: 'alice', conversationId, executionId: apiProviderResume.value.execution.executionId });
  assert.equal(apiIncompleteCapture.status, 200, JSON.stringify(apiIncompleteCapture.value));
  assert.equal(apiIncompleteCapture.value.assessment.code, 'PHASE_RESPONSE_INVALID');
  const apiIncompleteDirectory = path.join(lastDirectory, 'browser-attempts', apiProviderResume.value.execution.executionId);
