  assert.deepEqual(await readFile(path.join(providerFailureDirectory, '阶段终态采集.json')), accessProviderCaptureBytes);

  assert.deepEqual(await readFile(acceptedArtifactFile), acceptedArtifactBytes);
  assert.deepEqual(await readFile(postFailureFile), postFailureBytes);
  assert.deepEqual(await readFile(stateFile), parentBytes);
  assert.deepEqual(await Promise.all(retainedRuntimeNames.map(name => readFile(path.join(runtimeDirectory, name)))), retainedRuntime);
